import json
from copy import deepcopy

def solve():
    houses = list(range(6))  # indices 0..5 representing houses 1..6

    Names = ['Peter', 'Bob', 'Carol', 'Eric', 'Alice', 'Arnold']
    Pets = ['bird', 'dog', 'cat', 'rabbit', 'fish', 'hamster']
    Styles = ['victorian', 'ranch', 'modern', 'mediterranean', 'colonial', 'craftsman']
    Birthdays = ['mar', 'sept', 'may', 'feb', 'jan', 'april']

    # Initialize arrays: index 0..5 for houses 1..6
    names = [None] * 6
    pets = [None] * 6
    styles = [None] * 6
    bdays = [None] * 6

    # Apply fixed clues
    # 3. May is in the second house.
    bdays[1] = 'may'
    # 4. Colonial in the second house.
    styles[1] = 'colonial'
    # 14. Peter is the person living in a colonial-style house. -> house 2
    names[1] = 'Peter'
    # 5. Carol is in the third house.
    names[2] = 'Carol'
    # 17. Carol is the person whose birthday is in March.
    bdays[2] = 'mar'
    # 8. Eric is in the sixth house.
    names[5] = 'Eric'
    # 18. The person in a Craftsman-style house is in the fourth house.
    styles[3] = 'craftsman'
    # 11. The person in a Craftsman-style house is Arnold.
    names[3] = 'Arnold'
    # 19. The person who owns a dog is in the fourth house.
    pets[3] = 'dog'

    # Helper functions
    def no_duplicates(arr):
        seen = set()
        for v in arr:
            if v is not None:
                if v in seen:
                    return False
                seen.add(v)
        return True

    def find_index(arr, value):
        for i, v in enumerate(arr):
            if v == value:
                return i
        return None

    def possible_style_at(pos, value, styles_arr):
        # If already assigned at pos:
        if styles_arr[pos] is not None:
            return styles_arr[pos] == value
        # House-specific constraints:
        # 6. Mediterranean is not in the sixth house (index 5).
        if value == 'mediterranean' and pos == 5:
            return False
        # 4. Colonial in second house only -> if trying to place colonial elsewhere, invalid
        if value == 'colonial' and pos != 1:
            return False
        if value != 'colonial' and pos == 1:
            # house 2 is fixed to colonial
            return False
        # 18. Craftsman in fourth house only
        if value == 'craftsman' and pos != 3:
            return False
        if value != 'craftsman' and pos == 3:
            return False
        # 12. Colonial left of modern, and colonial is at index 1 => modern must be >1
        if value == 'modern' and pos <= 1:
            return False
        return True

    def possible_pet_at(pos, value, pets_arr, bdays_arr, styles_arr):
        # If already assigned at pos:
        if pets_arr[pos] is not None:
            return pets_arr[pos] == value
        # 19. Dog is in the fourth house only
        if value == 'dog' and pos != 3:
            return False
        if value != 'dog' and pos == 3:
            return False
        # 13. Fish is not in the second house (index 1)
        if value == 'fish' and pos == 1:
            return False
        # 1. Hamster to the right of March
        mar_idx = find_index(bdays_arr, 'mar')
        if value == 'hamster' and mar_idx is not None:
            if pos <= mar_idx:
                return False
        return True

    def is_consistent(names_arr, pets_arr, styles_arr, bdays_arr):
        # All-different checks
        if not no_duplicates(names_arr): return False
        if not no_duplicates(pets_arr): return False
        if not no_duplicates(styles_arr): return False
        if not no_duplicates(bdays_arr): return False

        # Fixed placements validation where assigned
        # House indices: 1->index0-based 0, etc.
        if bdays_arr[1] is not None and bdays_arr[1] != 'may': return False
        if styles_arr[1] is not None and styles_arr[1] != 'colonial': return False
        if names_arr[1] is not None and names_arr[1] != 'Peter': return False
        if names_arr[2] is not None and names_arr[2] != 'Carol': return False
        if bdays_arr[2] is not None and bdays_arr[2] != 'mar': return False
        if names_arr[5] is not None and names_arr[5] != 'Eric': return False
        if styles_arr[3] is not None and styles_arr[3] != 'craftsman': return False
        if names_arr[3] is not None and names_arr[3] != 'Arnold': return False
        if pets_arr[3] is not None and pets_arr[3] != 'dog': return False

        # 6. Mediterranean not in the sixth house
        if styles_arr[5] == 'mediterranean':
            return False

        # 11. Craftsman is Arnold
        pos_crafts = find_index(styles_arr, 'craftsman')
        pos_arn = find_index(names_arr, 'Arnold')
        if pos_crafts is not None and pos_arn is not None:
            if pos_crafts != pos_arn:
                return False

        # 14. Peter is the person living in a colonial-style house
        pos_col = find_index(styles_arr, 'colonial')
        pos_peter = find_index(names_arr, 'Peter')
        if pos_col is not None and pos_peter is not None:
            if pos_col != pos_peter:
                return False

        # 17. Carol is March
        pos_carol = find_index(names_arr, 'Carol')
        pos_mar = find_index(bdays_arr, 'mar')
        if pos_carol is not None and pos_mar is not None:
            if pos_carol != pos_mar:
                return False

        # 1. Hamster right of March
        pos_ham = find_index(pets_arr, 'hamster')
        if pos_mar is not None and pos_ham is not None:
            if not (pos_ham > pos_mar):
                return False
        elif pos_ham is None and pos_mar is not None:
            # Ensure at least one place remains to the right for hamster
            ok = False
            for i in range(pos_mar + 1, 6):
                if possible_pet_at(i, 'hamster', pets_arr, bdays_arr, styles_arr):
                    ok = True
                    break
            if not ok:
                return False

        # 2. January left of September
        pos_jan = find_index(bdays_arr, 'jan')
        pos_sept = find_index(bdays_arr, 'sept')
        if pos_jan is not None and pos_sept is not None:
            if not (pos_jan < pos_sept):
                return False
        elif pos_jan is not None and pos_sept is None:
            # need some spot to the right for September
            ok = False
            for i in range(pos_jan + 1, 6):
                if bdays_arr[i] is None or bdays_arr[i] == 'sept':
                    ok = True
                    break
            if not ok:
                return False
        elif pos_jan is None and pos_sept is not None:
            ok = False
            for i in range(0, pos_sept):
                if bdays_arr[i] is None or bdays_arr[i] == 'jan':
                    ok = True
                    break
            if not ok:
                return False

        # 7. Fish right of Bob
        pos_bob = find_index(names_arr, 'Bob')
        pos_fish = find_index(pets_arr, 'fish')
        if pos_bob is not None and pos_fish is not None:
            if not (pos_fish > pos_bob):
                return False
        elif pos_bob is not None and pos_fish is None:
            ok = False
            for i in range(pos_bob + 1, 6):
                if i == 1:
                    continue  # cannot be second house
                if pets_arr[i] is None or pets_arr[i] == 'fish':
                    ok = True
                    break
            if not ok:
                return False
        elif pos_bob is None and pos_fish is not None:
            ok = False
            for i in range(0, pos_fish):
                if names_arr[i] is None or names_arr[i] == 'Bob':
                    ok = True
                    break
            if not ok:
                return False

        # 9. One house between cat and Victorian (distance 2)
        pos_cat = find_index(pets_arr, 'cat')
        pos_vic = find_index(styles_arr, 'victorian')
        if pos_cat is not None and pos_vic is not None:
            if abs(pos_cat - pos_vic) != 2:
                return False
        elif pos_cat is not None and pos_vic is None:
            candidates = [pos_cat - 2, pos_cat + 2]
            ok = False
            for c in candidates:
                if 0 <= c < 6 and possible_style_at(c, 'victorian', styles_arr):
                    ok = True
                    break
            if not ok:
                return False
        elif pos_cat is None and pos_vic is not None:
            candidates = [pos_vic - 2, pos_vic + 2]
            ok = False
            for c in candidates:
                if 0 <= c < 6 and (pets_arr[c] is None or pets_arr[c] == 'cat'):
                    ok = True
                    break
            if not ok:
                return False

        # 10. Two houses between Victorian and hamster (distance 3)
        if pos_vic is not None and pos_ham is not None:
            if abs(pos_vic - pos_ham) != 3:
                return False
        elif pos_vic is not None and pos_ham is None:
            candidates = [pos_vic - 3, pos_vic + 3]
            ok = False
            for c in candidates:
                if 0 <= c < 6 and possible_pet_at(c, 'hamster', pets_arr, bdays_arr, styles_arr):
                    ok = True
                    break
            if not ok:
                return False
        elif pos_vic is None and pos_ham is not None:
            candidates = [pos_ham - 3, pos_ham + 3]
            ok = False
            for c in candidates:
                if 0 <= c < 6 and possible_style_at(c, 'victorian', styles_arr):
                    ok = True
                    break
            if not ok:
                return False

        # 12. Colonial left of modern
        pos_mod = find_index(styles_arr, 'modern')
        if pos_col is not None and pos_mod is not None:
            if not (pos_col < pos_mod):
                return False
        elif pos_col is not None and pos_mod is None:
            ok = False
            for i in range(pos_col + 1, 6):
                if possible_style_at(i, 'modern', styles_arr):
                    ok = True
                    break
            if not ok:
                return False

        # 13. Fish not in second house
        if pets_arr[1] == 'fish':
            return False

        # 15. January directly left of April
        pos_apr = find_index(bdays_arr, 'april')
        if pos_jan is not None and pos_apr is not None:
            if pos_apr != pos_jan + 1:
                return False
        elif pos_jan is not None and pos_apr is None:
            j = pos_jan + 1
            if j >= 6:
                return False
            if not (bdays_arr[j] is None or bdays_arr[j] == 'april'):
                return False
        elif pos_jan is None and pos_apr is not None:
            j = pos_apr - 1
            if j < 0:
                return False
            if not (bdays_arr[j] is None or bdays_arr[j] == 'jan'):
                return False

        # 16. One house between bird and modern (distance 2)
        pos_bird = find_index(pets_arr, 'bird')
        if pos_bird is not None and pos_mod is not None:
            if abs(pos_bird - pos_mod) != 2:
                return False
        elif pos_bird is not None and pos_mod is None:
            candidates = [pos_bird - 2, pos_bird + 2]
            ok = False
            for c in candidates:
                if 0 <= c < 6 and possible_style_at(c, 'modern', styles_arr):
                    ok = True
                    break
            if not ok:
                return False
        elif pos_bird is None and pos_mod is not None:
            candidates = [pos_mod - 2, pos_mod + 2]
            ok = False
            for c in candidates:
                if 0 <= c < 6 and (pets_arr[c] is None or pets_arr[c] == 'bird'):
                    ok = True
                    break
            if not ok:
                return False

        # 6 already handled; 7 handled; 8 fixed; 9 handled; 10 handled; 11 handled; 12 handled; 13 handled; 14 handled; 15 handled; 16 handled; 17 handled; 18,19 fixed

        return True

    # Domains for variable selection
    names_all = set(Names)
    pets_all = set(Pets)
    styles_all = set(Styles)
    bdays_all = set(Birthdays)

    def get_domain(attr, idx, names_arr, pets_arr, styles_arr, bdays_arr):
        if attr == 'name':
            if names_arr[idx] is not None:
                return [names_arr[idx]]
            # Fixed positions already assigned
            used = set(v for v in names_arr if v is not None)
            domain = list(names_all - used)
            return domain
        elif attr == 'pet':
            if pets_arr[idx] is not None:
                return [pets_arr[idx]]
            used = set(v for v in pets_arr if v is not None)
            domain = list(pets_all - used)
            # House-specific restriction: 13 fish not in second house
            if idx == 1 and 'fish' in domain:
                domain.remove('fish')
            # House-specific restriction: 19 dog in fourth house only
            if idx != 3 and 'dog' in domain:
                domain.remove('dog')
            if idx == 3:
                domain = ['dog']
            return domain
        elif attr == 'style':
            if styles_arr[idx] is not None:
                return [styles_arr[idx]]
            used = set(v for v in styles_arr if v is not None)
            domain = list(styles_all - used)
            # Apply house-specific restrictions
            # 6 Mediterranean not in 6th
            if idx == 5 and 'mediterranean' in domain:
                domain.remove('mediterranean')
            # 12 modern must be > house 2 (index >1)
            if idx <= 1 and 'modern' in domain:
                domain.remove('modern')
            # 4 colonial only at second house; 18 craftsman only at fourth house
            if idx != 1 and 'colonial' in domain:
                domain.remove('colonial')
            if idx != 3 and 'craftsman' in domain:
                domain.remove('craftsman')
            return domain
        elif attr == 'bday':
            if bdays_arr[idx] is not None:
                return [bdays_arr[idx]]
            used = set(v for v in bdays_arr if v is not None)
            domain = list(bdays_all - used)
            # House-specific: May at second only, March at third only already assigned
            if idx != 1 and 'may' in domain:
                domain.remove('may')
            if idx != 2 and 'mar' in domain:
                domain.remove('mar')
            # 15 Jan directly left of April implies April not in house 1 and Jan not in house 6
            if idx == 0 and 'april' in domain:
                domain.remove('april')
            if idx == 5 and 'jan' in domain:
                domain.remove('jan')
            return domain
        else:
            return []

    def choose_next_variable(names_arr, pets_arr, styles_arr, bdays_arr):
        variables = []
        # Order by heuristic: mix attributes; we'll select the one with smallest domain
        for idx in range(6):
            if names_arr[idx] is None:
                variables.append(('name', idx))
            if pets_arr[idx] is None:
                variables.append(('pet', idx))
            if styles_arr[idx] is None:
                variables.append(('style', idx))
            if bdays_arr[idx] is None:
                variables.append(('bday', idx))
        # Compute domains and pick smallest
        best = None
        best_domain = None
        min_size = float('inf')
        for var in variables:
            attr, idx = var
            dom = get_domain(attr, idx, names_arr, pets_arr, styles_arr, bdays_arr)
            # Early fail
            if len(dom) == 0:
                return None, []
            if len(dom) < min_size:
                min_size = len(dom)
                best = var
                best_domain = dom
                if min_size == 1:
                    # Can't get smaller
                    pass
        return best, best_domain if best is not None else []

    solutions = []

    def backtrack(names_arr, pets_arr, styles_arr, bdays_arr):
        if not is_consistent(names_arr, pets_arr, styles_arr, bdays_arr):
            return
        # Check completion
        if all(v is not None for v in names_arr) and \
           all(v is not None for v in pets_arr) and \
           all(v is not None for v in styles_arr) and \
           all(v is not None for v in bdays_arr):
            solutions.append((deepcopy(names_arr), deepcopy(pets_arr), deepcopy(styles_arr), deepcopy(bdays_arr)))
            return
        var, domain = choose_next_variable(names_arr, pets_arr, styles_arr, bdays_arr)
        if var is None:
            return
        attr, idx = var
        for val in domain:
            # Assign
            if attr == 'name':
                names_arr[idx] = val
            elif attr == 'pet':
                pets_arr[idx] = val
            elif attr == 'style':
                styles_arr[idx] = val
            elif attr == 'bday':
                bdays_arr[idx] = val

            backtrack(names_arr, pets_arr, styles_arr, bdays_arr)

            # Unassign
            if attr == 'name':
                names_arr[idx] = None
            elif attr == 'pet':
                pets_arr[idx] = None
            elif attr == 'style':
                styles_arr[idx] = None
            elif attr == 'bday':
                bdays_arr[idx] = None

    backtrack(names, pets, styles, bdays)

    if not solutions:
        raise RuntimeError("No solution found")

    # Assume unique solution
    names_sol, pets_sol, styles_sol, bdays_sol = solutions[0]

    # Build JSON output
    header = ["House", "Name", "Pet", "HouseStyle", "Birthday"]
    rows = []
    for i in range(6):
        # House number as string
        row = [str(i + 1), names_sol[i], pets_sol[i], styles_sol[i], bdays_sol[i]]
        rows.append(row)

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    return output

if __name__ == "__main__":
    result = solve()
    print(json.dumps(result, ensure_ascii=False))
